/* @lc app=leetcode id=1793 lang=kotlin */ class Solution { fun maximumScore(nums: IntArray, k: Int): Int = intArrayOf(k, k, nums[k], nums[k]).apply { repeat(nums.size - 1) { apply { if (this[0] == 0) this[1]++ else if (this[1] == nums.size - 1) this[0]-- else if (nums[this[1] + 1] > nums[this[0] - 1]) this[1]++ else this[0]-- }.apply { this[2] = minOf(this[2], minOf(nums[this[0]], nums[this[1]])) }.apply { this[3] = maxOf(this[3], this[2] * (this[1] - this[0] + 1)) } } }[3] }